  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (723::BIGINT, 'En clases el ambiente era un poco tenso por la profe, explica enredado y aveces se le iban detalles. En definitiva hay mejores opciones pero al final el curso es pasable, recuerde llevar la libreta completa'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, 'f6e1825d69086cc47165b6a88730332585779b8acaeed50067533bcfd1dc34fb'::TEXT, ARRAY[567]::BIGINT[]),
    (723::BIGINT, 'Es la peor de lejos para llevar este curso, nunca me había topado con una persona tan insoportable e invivible como Lilliana. Si no sabe algo de la materia ella va a buscar humillarlo y que todos se den cuenta que usted no sabe, aunque sea materia de un curso anterior. Es la Anti-cabra, NO matricule'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'b3a96ecd97454f9373d924fdb1972705e879defd4927e39c85362355f2653e48'::TEXT, ARRAY[567]::BIGINT[]),
    (723::BIGINT, 'Veo muchos comentarios de esta profesora diciendo que es mala y que es odiosa, pero la realidad es otra, recuerdo cundo estaba en el laboratorio que muchos no prestaban atención y luego andaban preguntando (eso a cualquier profe le enoja)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'eb3e4474b9e7847fde7b0795e07a84d48fd4827f6337a190540a2eb03bbbffd1'::TEXT, ARRAY[567]::BIGINT[]),
    (723::BIGINT, 'Es una profesora difícil, algo tosca, muy exigente con las libretas, da ayuda al estudiante pero al mismo tiempo se ofusca de que uno no le entienda o no traiga la práctica memorizada.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'cd4905dc92203e3d10704505be7cabfa06a975a39e1fcdee5b9b0163c5f002ee'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ella en sí es un poco grosera, pero si le toca matricular con ella, desde la 1 práctica lleve todo lo que se necesita, el cuadro de constantes completos, ya que sin eso ella pone 0 en el quiz y en el informe. SI sigue a la perfección instrucciones, le va a ir bien. revisa los primeros 5 informes'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c89d331d930d19a74f21b41b552562450a29aef38d3301630753d5f24ad33698'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'El curso en si es pesado, y ya está predispuesto lo que se va a realizar, entonces el profesor no tiene mucha libertad. Ella explica bastante bien, si es concha pero muchos profes de laboratorio tienen una actitud igual como de superioridad entonces no es nada abnormal.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2023-12-21T00:00:00+00:00'::TIMESTAMPTZ, '34bea023db44d63531d88e26c9b2b8b66db4cbf3bc242dfd7bb064c42b6a3095'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Dice que uno le puede preguntar todo las veces que quiera pero uno va y le pregunta algo y responde toda odiosa. Además de que lo trata a uno como tonto si no entiende algo, en lugar de dejar de jugar de intrépida y explicar bien lanza comentarios que nadie le pidió, yo no la recomendaría.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-11-15T00:00:00+00:00'::TIMESTAMPTZ, '40e64b3b723b1ab527bcb0032f986a507820aa3fd9ca06f36fac908d64562775'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'La gente la considera como mala profe, pero estoy en desacuerdo. Es verdad que es muy tosca con las personas que no aprenden al ritmo que le gustaría, pero también es verdad que deja todo claro en clases y da espacio para dudas. No es mala profe pero tampoco la recomiendo'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-05-19T00:00:00+00:00'::TIMESTAMPTZ, 'ecebe99b6aeaaeeeebab2d0ae58ec40293eac3e0fbee170ac15caa538febabfd'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Profe Vaga'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2022-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'cee4766393947ce3a609802b55cda9c3b1afd9caf235d2a8074b9264081aaf05'::TEXT, ARRAY[567]::BIGINT[]),
    (723::BIGINT, 'Una profe muy vaga, en la clase solo vemos el video del experimento y ya, no explica mucho.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, '98b315d7f5798ae718eb86aacbd3c6b4de8c2d20cee58fa3ca125392cf1a5e2c'::TEXT, ARRAY[567]::BIGINT[]),
    (723::BIGINT, 'Mala explicandop y califica bastante duro'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'bd7b330cc15303e4d409e4de29c9015690c8a5c3f78c9f457caad26c4e391a34'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Clases cortas pero super aburridas, y como si uno lo supiera todo. No ha logrado adaptarse a la virtualidad y quiere que todo se haga como si fuera presencial, además de que si se le pregunta algo va a contestar que hay que volver a leer el documento.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-06-08T00:00:00+00:00'::TIMESTAMPTZ, '6a7577e4c91874af9ff17453611b2f17db59361bf7e0fb65a4213020a9756348'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, '[Virtual] Los informes los califica demasiado rudos, pero está dispuesta a ayudar siempre y cuando se lo haga saber con tiempo. Las clases son cortas pero aburridas, le gusta que la gente participe.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '60a1dbeebff0131b6be0db38cade297c07123cab17cbd1fdd82bba4b49cd7998'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2020-12-19T00:00:00+00:00'::TIMESTAMPTZ, '0d12716ea3633bcfe014fb538f20c39d909cda5209c1507c2fb2d84af4de7e4f'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Muy mala profe, sumamente arrogante y es de esas que piensan que su materia es la unica que el estudiante lleva. Aun mas en la modalidad virtual, no logra adaptarse y pretende que todo se haga como en lo presencial.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2020-10-02T00:00:00+00:00'::TIMESTAMPTZ, '994ae8c460ff88cc24976825a10673bb6dbfe2e9f2b8c521fa1bd17c51a60418'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Es un poco intimidante jaja pero de verdad le interesa que los estudiantes aprendan. Dicho esto, si costó que se adaptara a la modalidad virtual y a la hora de evaluar era muy estricta.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '5591c564fa5230d8e51047554c5b2e42de5e246118a765aca711cf6322892ac7'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'La profe conoce mucho de la materia pero solo hace una explicación por encima como si ya se supiera la materia, devuelve informes con nota pero sin decir por que le baja puntos'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'b778c4c404ef2d0d1969969eb7530cfaa756585ead448d8818ec9ffc0eb025d1'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Tiene muchísimo conocimiento en Química pero en ciertos temas asume que el estudiante lo sabe todo. Deben haber buenas bases de QI para llevar el curso con ella. Cumpla con todo, preste atención en clase y a lo que dice y no habrá problema para aprobar el curso.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, 'e1a0c9e7932623718c7b398af859817dc230f54d27d52f5e4f4144a8c738ce48'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Que señora más detestable, la profesora más delicada que pueden escoger para el lab'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-02-25T00:00:00+00:00'::TIMESTAMPTZ, '871343954e3a02f5dcf33b2ade93b26e007b040391cebc9dd4d85d1d62208b82'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Es excelente profesora'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'cfb654e7d178a534a1bb5e0de5a31831acac259acb65a733a3256c9bed7280c1'::TEXT, ARRAY[3217]::BIGINT[]),
    (723::BIGINT, 'Si tiene buenas bases de laboratorio de química l métalo con ella. Los exámenes cortos salen del cuestionario previo de la práctica y aún así la gente se saca mala nota. Hay que hacer la libreta a conciencia'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'c89c5b0c39c99ea4ccf95cf673a7cbe93bcbdd642b08ec36bdc67556cd2f831d'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Buena profe, la recomiendo! Puede que califique duro, pero para salir bien, hay que poner atención a las instrucciones y simplemente hacer lo que se tiene que hacer.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-11-09T00:00:00+00:00'::TIMESTAMPTZ, '0f715f5fe8d2ad64b1ac19148537594b58fb030fa9f14befba96b5731d5dc68d'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Califica demasiado duro los quices, informes y el primer examen. Explica muy a la antigua y a veces la clase es muy aburrida.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '11d546d99d441ed3aea3f283a99e6b25f8dbe0dc81904081a370ac13b7dce1a6'::TEXT, ARRAY[567]::BIGINT[]),
    (723::BIGINT, 'No vale la pena llevar el curso con ella'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Asistencia obligatoria']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '7a2923a67581acd4b2467349fa5eeac5c459c3bab534a02fdfda950f34341fe9'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'La profe no es mala explicando pero es super ruda, si penso que le va a ayudar, se lo soño! La profe califica HIPER duro, por cualquier tontera le quita la mayor cantidad de puntos y en los exámenes es peor!'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-21T00:00:00+00:00'::TIMESTAMPTZ, '0c2904528c68e525afe2790dee806e3bfec13ae6c6ba67c36eba7363f008611b'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Si tiene la opción de no matricular con ella no lo haga. Preguntarle algo, la mayoría de veces implica estar listo para ser ridiculizado en público, además no es muy clara explicando. Revisa duro los informes, más considerada en los parciales.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-17T00:00:00+00:00'::TIMESTAMPTZ, '749b271fa98726663c722976aa8a6974d1774145afaa9a43ccba3520bb7507b2'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-13T00:00:00+00:00'::TIMESTAMPTZ, '7b47fc98536254249222b696fe127481e8f73dd4cb21d317ba40d90b781e6ba7'::TEXT, ARRAY[567]::BIGINT[]),
    (723::BIGINT, 'Es muy buena profe y hasta divertida, califica los informes duro pero en los exámenes es más compresiva.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Clases excelentes']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '0a3b04037b93d89c7d37a40a26fa86890305971c148a348799a4fb3409d4ada5'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'La profe es súper buena persona y divertida, es un poco clara pero los temas no son complejos entonces con leer la teoria es suficiente, Los quices son muuuuuuuuuy fáciles. Califica duro los informes pero en los examenes es bastante comprensiva'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, '8d6631dfba2d5691bfb2fddafba3a6e0111c27e6709643eb05c517596c2106fb'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2017-02-05T00:00:00+00:00'::TIMESTAMPTZ, '8e21935645641ae0bc0d863337863fd5baea19e51b2d263a3f12a2f2c8528d01'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Como profesora está bien, empieza la clase como 2 minutos antes de la hora, entonces es bueno llegar temprano. No siempre ayuda al preguntarle, pero el curso no es tan difícil. Recomiendo estudiar bien la práctica para los quices.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, '2d63cfd667c37bf2c20113376aeb3282e391c2bfe1748614b938ff53ffd944d4'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Es excelente persona, solo que como profe a veces se confunde y no sabe como explicar, los quices son muy fáciles y califica normal. Las clases son muy aburridas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '9ddcff441a00c8333327e059ff806e6c3bfdf41aabb313280f55ad823ed0c767'::TEXT, ARRAY[567]::BIGINT[]),
    (723::BIGINT, 'No se le entiende'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'bc2c05292a43abfe4479173bcd3f14fa6840356bbc9ab502aa76217ac6e23bae'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'La profe a veces se comporta un toque grosera pero no hay que hacerle caso... Aparte de eso es muy buena gente y explica bien. No estresa mucho con la libreta, pero siempre hay que llevarla completa aunque no la revise rigurosamente'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'c27b4bc2f6c7f866d076c47aed61e848699c7e2b3255ae642f52a48ebac09180'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Buena profesora y trata de ayudar al estudiante'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'e94de6f3f69235210039ce6931ba276c79660b548b6833e1919a426fd37af076'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'En consulta ayuda un montón pero si es exigente en sus clases.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2016-02-01T00:00:00+00:00'::TIMESTAMPTZ, '43866bc4d10bc9fc69fa4abe3e4a5e5762a3887d4699adf16912ec18740a984a'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'La verdad no me pareció buena, no se preocupa por el estudiante'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, '4ced485ff75160b3cd472bf4d6915c5919fcbec1ef0e8f2f622d3a692090a3c9'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'c527c2b163fc645169b3e9c20680cca2d2b979b0feac8471867f6ae23b4db081'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Es media loca, pero explica bien y es buena gente.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '6109a065470ecaba18b3bf029ba8148e2716b63bab0fa35ed1deffa1fb12bb44'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Tiene una actitud hacia los estudiantes un poco mala, no le gusta que le pregunten cosas, pero explica bien y no es exigente con la libreta, los quices son fáciles y califica ligeramente suave.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-19T00:00:00+00:00'::TIMESTAMPTZ, '80c3df386056c8948e9192691721debed44265c407d4e4aaadabae5b2fe7398a'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'No estresa con la libreta y explica muy bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'ae89015f29cc1429f80b0c65c00a27befe1a013f49f0818c1264d4f1764a7570'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'f4d0148c1baf9b4955c0b1a4c9af63727fc95ea240f08f59f4f11b409e241335'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Mucha práctica, poca teoría. Muy buena gente pero cuando se trata de la materia se pone muy seria.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-02T00:00:00+00:00'::TIMESTAMPTZ, '6f0cb14e20f66ce68574cac326d538cbc1eec328c9292b5ebbf272f1d0490bf3'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Es muy buena profe y si le pone le ayuda bastante! si ud es un irresponsable no meta con ella porque le va a caer mal.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'e677760dd21edd42ca7ee22f0f2fcd316a35d47d6da8b10803a441c51cb03fb5'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Cuesta entenderle, al ser una materia de bastantes calculos...'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '2e8e5b73449aae70b7379a25b8d4abaac3f03d208092aa3b79a56633ea98d818'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Lo único que veo malo es que hace tareas con valor de quiz pero esta las califica como buena o mala en base al resultado final y no al procedimiento completo, por lo demás excelente!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-20T00:00:00+00:00'::TIMESTAMPTZ, '46496c0d1b9aacf24a6b2cfd46f10afe233ce2ea0c4960cae8ca7322a9dde854'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '963f4191aa39d113be442bb9d7681ea72f6ea19c9a0feab442591fbeb9f65c64'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'No es muy buena'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-11T00:00:00+00:00'::TIMESTAMPTZ, '5d53c841d154bfe54ae0a407666c5cfba92d26c2ec84fdf2f28ce0b8f29ac4a7'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ella es bastante buena, en sí le interesa más la práctica por lo que hace muchos problemas y explica poca teoría. Es muy amable y se preocupa por los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-04T00:00:00+00:00'::TIMESTAMPTZ, '4baeafe97680f6347f28442553f5598c2c955dd3d6d9b63869917ef8d73344e3'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'MUY MALA PROFESORA!!!! DA UNOS EJEMPLOS TODOS ESTÚPIDOS Y HAY PROBLEMAS QUE NO LE SALEN, ADEMAS ES TODA AMARGADA Y LOS QUICES LOS CALIFICA BINARIO. LA VERDAD NO LA RECOMIENDO!!!!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '4d564a4c8755d3a18057e4771024ecd4090268305f99a41e94f7f91ded019dec'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'a32784d73501515a5112588b5745ff76fd1dda3ddec80c8efe0096003904fcab'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Esta profe es muy buena gente y si quiere que la gente pase, tambien hace muchos quices que ayudan a estudiar y a tener buenas notas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-31T00:00:00+00:00'::TIMESTAMPTZ, '74c7b42bb2890c1434f0247029df1396f79cc992e3cb9684561a0a1055291f6b'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Excelente profe, personalmente le entiendo bastante. Da ejemplos bastante concretos y la verdad es genial. deja tareas que luego cuenta como quices, lo que es mejor para el promedio de quices,valga la rebundancia'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-30T00:00:00+00:00'::TIMESTAMPTZ, '2d78cad8116359b80614bbc5a0e840fd355d65034b3c64dd8b756522a80c42fd'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '9b4afc54513e08caf989cc58ff356359c4bc44bd8e6e1cf91091416cb44e2fb6'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'En lo personal, no es apta para dar clases de teoria, tal vez laboratorio sea mejor!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-26T00:00:00+00:00'::TIMESTAMPTZ, '998c2a627c752260f9d7e1ee2e5bf350ca0ae73bc9a9da15b500a178edb6f9ff'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-02T00:00:00+00:00'::TIMESTAMPTZ, '553c70230914daae8ffb427b68410c2ad70141f51a28f2fd930187b3d4fd3f08'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Es un poco difícil entenderle porque va muy rápido, pero hace mucha práctica en clases y siempre da ejemplos de todo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-27T00:00:00+00:00'::TIMESTAMPTZ, '96f3d14c5fc0cc84aa57c4b7c9f7473b2b3362063fcffe7fee285c29025d1341'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-26T00:00:00+00:00'::TIMESTAMPTZ, '7f59c3364edc33b5c7d94bc40a1832dd0f6fba12b4744d8a486f32c3efd93b43'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-29T00:00:00+00:00'::TIMESTAMPTZ, '2bfddcad1e9f9b4330dd24a89a07cbbdbe0585810dfaedfc446d93bb423b11a3'::TEXT, ARRAY[567]::BIGINT[]),
    (723::BIGINT, 'Se enfoca mucho en lo practico, lo teorico lo ve solo por encima.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '20e81a1094d6e1eff06360862afa04414e2420887f43e8fae5f7ed988dc80168'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Muy buena gente, se enoja cuando le preguntan algo pero igual siempre responde. Hace centros, y mucha practica en clases, al menos en quimica II! Recomendada al 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '6c65c01771a9fde0ec32d507036ad4b81f7584d80cb1a79a5f8387f643decef4'::TEXT, ARRAY[613]::BIGINT[]),
    (723::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'f1029767b490916e1ac874ba7c3008a0be44164c1e1740dc5a241f14b39e38ea'::TEXT, ARRAY[567]::BIGINT[]),
    (723::BIGINT, 'Profe pura vida.Da centros durante todo el semestre. Le interesa que los estudiantes aprendan y disfruten la química. Ayuda al final, si ve que el estudiante se esfuerza.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '619bb7884c618d93d0a42b0dc4bddbccb80f6f37b3f1a9af45010f8dc2649186'::TEXT, ARRAY[613]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
